//! JSON-RPC 2.0 / MCP wire shapes and the constants that pin which spec
//! revision this server speaks. See `mcp/mod.rs` for why these are
//! hand-written rather than generated by the `rmcp` SDK.

use serde_json::{json, Value};

/// The MCP protocol revision this server prefers, echoed back verbatim when
/// the client asks for it or for anything unrecognized (the negotiation
/// algorithm the spec describes: the server names a version it actually
/// supports, and the client decides whether to continue).
pub const LATEST_PROTOCOL_VERSION: &str = "2025-06-18";

/// Every revision this server's tiny surface (`initialize`, `tools/list`,
/// `tools/call`, `ping`) behaves identically under — there is no
/// version-dependent feature here to gate on.
pub const SUPPORTED_PROTOCOL_VERSIONS: &[&str] = &["2025-06-18", "2025-03-26", "2024-11-05"];

/// Sent as `instructions` in `initialize`'s result (F-15). Clients load
/// tools lazily or only by group, so a model may see one tool's description
/// and nothing else; this is the map of the whole surface, in the order the
/// work goes.
pub const SERVER_INSTRUCTIONS: &str = "\
AWIC drives bench instruments on this machine: logic analyzers, a USB oscilloscope, serial ports \
and switchable USB hub ports. Results are summaries and pictures, never bulk samples.

Workflow:
1. `list_instruments` finds the devices; `device` everywhere is its bus-path id (e.g. \"3-3.4.2\").
2. Unknown wiring on a logic analyzer: `survey_channels` names what each line carries (UART and \
its baud, I2C, SPI, clocks), with protocol guesses that give the channel mapping for `decode`.
3. One shot: `configure_acquisition` then `capture` returns a `capture://` handle and per-channel \
statistics. Over time: `start_recording`, then `search_pattern` / `wait_for_pattern` to find \
events and `snapshot_recording` to turn a span into a capture.
4. Read the bus: `decode` with `format: \"transactions\"` gives one entry per I2C/SPI/UART/CAN/\
1-Wire transaction plus a `summary` (counts, NACKs, errors, bursts); identical transactions in a \
row are folded into one entry with `repeat`.
5. Look and measure: `measure` for exact numbers, `read_capture` for a decimated preview, \
`render_view` for a picture with its measurements (waveform, eye, histogram, anomalies). Every \
picture comes with a `url` to save it with curl; `format: \"png\"` if the client cannot show SVG.

Channels are hardware numbers in every tool: logic analyzer D0-D7 are 0-7 (D4 is 4), oscilloscope \
CH1 is 0 and CH2 is 1. Pictures and notes call them D4 / CH1.

Windows: `t0_s`/`t1_s` are seconds from the start of the capture (or of the recording's retained \
span); `render_view` also takes `span_s`, and `read_capture`/`render_view` take `sample0`/\
`sample1`, the sample numbers `decode` reports as `start_sample`/`end_sample`. Every time you \
compute must use the `rate_hz` the device reports back, not the one you asked for.

Trust the result's own caveats: read `note`, `notes`, `truncated` and `omitted` before drawing a \
conclusion — they say when a number is a bound, a window was cut, a line never moved or a \
recording had a gap. Captures are evicted when the store fills (the error says so); take a new \
one rather than guessing.";

pub const PARSE_ERROR: i64 = -32700;
pub const INVALID_REQUEST: i64 = -32600;
pub const METHOD_NOT_FOUND: i64 = -32601;
pub const INVALID_PARAMS: i64 = -32602;
pub const INTERNAL_ERROR: i64 = -32603;

/// Picks the protocol version to report in `initialize`'s result: the
/// client's own request if we support it, otherwise our preferred latest —
/// never an error, since an unrecognized version is the client's problem to
/// react to (per spec), not this server's problem to refuse.
pub fn negotiate_protocol_version(requested: &str) -> &'static str {
    SUPPORTED_PROTOCOL_VERSIONS
        .iter()
        .find(|&&v| v == requested)
        .copied()
        .unwrap_or(LATEST_PROTOCOL_VERSION)
}

/// A successful JSON-RPC response.
pub fn success(id: Value, result: Value) -> Value {
    json!({ "jsonrpc": "2.0", "id": id, "result": result })
}

/// A protocol-level JSON-RPC error (malformed request, unknown method,
/// bad params) — distinct from a *tool* error, which is reported inside a
/// successful `tools/call` result with `isError: true` (MCP spec: tool
/// execution failures are data, not transport failures).
pub fn error(id: Value, code: i64, message: impl Into<String>) -> Value {
    json!({ "jsonrpc": "2.0", "id": id, "error": { "code": code, "message": message.into() } })
}

/// A successful `tools/call` result whose tool ran without error: one text
/// content block (compact JSON — an agent can read it directly) plus the
/// same value as `structuredContent`, for clients that parse that instead
/// (both carry the same bounded, no-bulk-data payload — SPEC §8.3).
pub fn tool_ok(value: Value) -> Value {
    let text = serde_json::to_string(&value).unwrap_or_else(|_| "null".to_string());
    json!({
        "content": [{ "type": "text", "text": text }],
        "structuredContent": value,
        "isError": false,
    })
}

/// A successful result that also carries a picture: the same text and
/// structured content as [`tool_ok`], plus an MCP `image` content block.
///
/// The image is a *second* channel, never the only one — the structured
/// result already carries every number the picture is labelled with, so a
/// client that cannot render images loses nothing but the shape. The picture's
/// bytes deliberately stay out of the text block, which would otherwise put
/// tens of kilobytes of path data into an agent's context for no benefit.
pub fn tool_ok_with_image(value: Value, mime_type: &str, data: String) -> Value {
    let text = serde_json::to_string(&value).unwrap_or_else(|_| "null".to_string());
    json!({
        "content": [
            { "type": "text", "text": text },
            { "type": "image", "mimeType": mime_type, "data": data },
        ],
        "structuredContent": value,
        "isError": false,
    })
}

/// A `tools/call` result reporting the tool itself failed — still a
/// successful JSON-RPC response (`isError: true` inside `result`), carrying
/// the server's own actionable `{code, msg}` (SPEC §3.1) as its text so an
/// agent can act on it without a second round trip.
pub fn tool_err(code: &str, msg: &str) -> Value {
    json!({
        "content": [{ "type": "text", "text": format!("{code}: {msg}") }],
        "isError": true,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn negotiate_echoes_a_supported_version() {
        assert_eq!(negotiate_protocol_version("2024-11-05"), "2024-11-05");
    }

    #[test]
    fn negotiate_falls_back_to_latest_for_unknown_version() {
        assert_eq!(
            negotiate_protocol_version("1999-01-01"),
            LATEST_PROTOCOL_VERSION
        );
    }

    #[test]
    fn an_image_result_keeps_the_bytes_out_of_the_text_block() {
        let v = tool_ok_with_image(
            json!({"eye_height": "3.19 V"}),
            "image/svg+xml",
            "QUJD".into(),
        );
        assert_eq!(v["content"][0]["type"], "text");
        assert!(v["content"][0]["text"].as_str().unwrap().contains("3.19 V"));
        assert!(
            !v["content"][0]["text"].as_str().unwrap().contains("QUJD"),
            "the picture must not be inlined into the text block"
        );
        assert_eq!(v["content"][1]["type"], "image");
        assert_eq!(v["content"][1]["mimeType"], "image/svg+xml");
        assert_eq!(v["content"][1]["data"], "QUJD");
        assert_eq!(v["structuredContent"]["eye_height"], "3.19 V");
        assert_eq!(v["isError"], false);
    }

    #[test]
    fn tool_ok_carries_both_text_and_structured_content() {
        let v = tool_ok(json!({"a": 1}));
        assert_eq!(v["isError"], false);
        assert_eq!(v["structuredContent"]["a"], 1);
        assert!(v["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("\"a\":1"));
    }

    #[test]
    fn tool_err_sets_is_error_true() {
        let v = tool_err("port_protected", "hub 3-3 port 4 is protected");
        assert_eq!(v["isError"], true);
        assert!(v["content"][0]["text"]
            .as_str()
            .unwrap()
            .starts_with("port_protected:"));
    }
}
